package app.rwun;
import android.content.Context;import android.os.SystemClock;import android.provider.Settings;import java.time.*;import java.util.*;import org.json.*;
/** Timer snapshots need no GPS, body-sensor permission, wake lock or continuously running CPU. */
final class IndoorState {
 static int boot(Context c){try{return Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT);}catch(Exception e){return (int)((System.currentTimeMillis()-SystemClock.elapsedRealtime())/60000);}}
 static JSONObject active(Context c){return new RunStore(c).v103().optJSONObject("activeIndoor");}
 static void start(Context c,String kind,int goal,String session,boolean phoneSteps)throws Exception{synchronized(RunStore.LOCK){RunStore s=new RunStore(c);if(s.resting()||!s.checkpoint().isEmpty()||s.indoorPending())throw new IllegalStateException("Review the hold or finish/recover the pending session first");int stage=BeginnerProgramme.stageFromId(session);if(stage>=0&&(stage!=CoachingMemory.stage(s)||!kind.equals("Run")))throw new IllegalStateException("Review the current beginner running stage before starting");JSONObject d=s.v103();JSONObject a=new JSONObject().put("id",UUID.randomUUID().toString()).put("kind",kind).put("date",LocalDate.now().toString()).put("startedAtWall",System.currentTimeMillis()).put("heartbeatWall",System.currentTimeMillis()).put("goal",goal).put("planned",session==null?"":session).put("step",0).put("stepStart",0).put("phoneSteps",phoneSteps).put("phoneStepCount",0).put("stepRaw",-1).put("stepEvent",0).put("stepResume",SystemClock.elapsedRealtimeNanos()).put("length",StepEstimate.sessionLength(d.optJSONObject("stepLengths")==null?0:d.getJSONObject("stepLengths").optDouble(kind,0),kind)).put("stepLengthCalibrated",d.optJSONObject("stepLengths")!=null&&d.getJSONObject("stepLengths").optDouble(kind,0)>=.2);V103Data.clock(a,new IndoorClock(0,SystemClock.elapsedRealtime(),boot(c),false,false));d.put("activeIndoor",a);s.v103(d);}Reminders.sessionNotification(c);IndoorStepService.sync(c);}
 static IndoorClock snapshot(Context c)throws Exception{synchronized(RunStore.LOCK){RunStore s=new RunStore(c);JSONObject d=s.v103(),a=d.optJSONObject("activeIndoor");if(a==null)return null;IndoorClock previous=V103Data.clock(a);IndoorClock clock=previous.snapshot(SystemClock.elapsedRealtime(),boot(c));if(previous.boot()!=boot(c)&&a.optBoolean("phoneSteps"))a.put("partialSteps",true).put("stepStatus","Phone restarted · resume to restart step tracking");V103Data.clock(a,clock);d.put("activeIndoor",a);s.v103(d);return clock;}}
 static void toggle(Context c)throws Exception{synchronized(RunStore.LOCK){IndoorStepService.flush();RunStore s=new RunStore(c);JSONObject d=s.v103(),a=d.optJSONObject("activeIndoor");if(a==null)return;IndoorClock clock=V103Data.clock(a).toggle(SystemClock.elapsedRealtime(),boot(c));if(!clock.paused()&&s.resting())throw new IllegalStateException("Training is on hold");V103Data.clock(a,clock);a.put("pausedAtWall",clock.paused()?System.currentTimeMillis():0).put("heartbeatWall",System.currentTimeMillis());a.put("stepRaw",-1).put("stepEvent",0).put("stepResume",SystemClock.elapsedRealtimeNanos());if(a.optBoolean("phoneSteps")){a.put("stepStatus",clock.paused()?"Step tracking paused":"Waiting for step sensor");if(!clock.paused())a.put("partialSteps",true);}s.v103(d);}Reminders.sessionNotification(c);IndoorStepService.sync(c);}
 static String trackingWarning(Context c,JSONObject a){try{long seconds=V103Data.clock(a).value(SystemClock.elapsedRealtime(),boot(c));long anchor=Math.max(a.optLong("stepResume"),a.optLong("stepMovementNanos",a.optLong("stepEvent")));long quiet=anchor<=0?seconds:Math.max(0,(SystemClock.elapsedRealtimeNanos()-anchor)/1000000000L);return StepEstimate.warning(seconds,a.optLong("phoneStepCount"),quiet,a.optBoolean("phoneSteps"),a.optBoolean("paused"));}catch(Exception e){return "Recording status unavailable · open diagnostics";}}
 static boolean finishForReview(Context c,String expected)throws Exception{synchronized(RunStore.LOCK){JSONObject a=active(c);if(a==null||!a.optString("id").equals(expected))return false;if(!V103Data.clock(a).paused())toggle(c);RunStore s=new RunStore(c);JSONObject d=s.v103();d.getJSONObject("activeIndoor").put("reviewPending",true);s.v103(d);return true;}}
 static long seconds(Context c){try{JSONObject a=active(c);return a==null?0:V103Data.clock(a).value(SystemClock.elapsedRealtime(),boot(c));}catch(Exception e){return 0;}}
 static void clear(Context c){synchronized(RunStore.LOCK){RunStore s=new RunStore(c);JSONObject d=s.v103();d.remove("activeIndoor");s.v103(d);}IndoorStepService.sync(c);c.getSystemService(android.app.NotificationManager.class).cancel(1030);Reminders.schedule(c);}
}
